-- LOZA catalogue, additive after 0003. Apply to isolated Preview first.
-- Source: owner PDF, Catalogue 2026-2027, SHA-256 recorded in each source snapshot.
-- A PDF price is displayed, but requires explicit owner confirmation before purchase.
CREATE TABLE IF NOT EXISTS product_catalog(
  product_id TEXT PRIMARY KEY REFERENCES products(id) ON DELETE RESTRICT,
  confirmed_price_kop INTEGER CHECK(confirmed_price_kop IS NULL OR (typeof(confirmed_price_kop)='integer' AND confirmed_price_kop BETWEEN 1 AND 100000000)),
  characteristics_confirmed INTEGER NOT NULL DEFAULT 0 CHECK(characteristics_confirmed IN(0,1)),
  source_json TEXT NOT NULL CHECK(json_valid(source_json))
);


-- Populate only missing prices on the first application. Never overwrite owner prices or stock.
UPDATE products SET price_kop=(SELECT json_extract(source_json,'$.priceKop') FROM product_catalog WHERE product_id=products.id)
  WHERE price_kop IS NULL AND id IN(SELECT product_id FROM product_catalog WHERE json_extract(source_json,'$.priceKop') IS NOT NULL)
    AND NOT EXISTS(SELECT 1 FROM loza_store_migrations WHERE version='0004_catalog_107');
-- Keep demo rows and historic order references, but archive them once all 107 real rows are present.
UPDATE products SET available=0 WHERE is_demo=1 AND available<>0
  AND (SELECT COUNT(*) FROM product_catalog)=107;

CREATE TRIGGER IF NOT EXISTS loza_catalog_price_guard_insert BEFORE INSERT ON products WHEN NEW.available=1 BEGIN
  SELECT RAISE(ABORT,'LOZA_PRICE_NOT_CONFIRMED');
END;
CREATE TRIGGER IF NOT EXISTS loza_catalog_price_guard_update BEFORE UPDATE ON products
WHEN NEW.available=1 AND (NEW.is_demo=1 OR NOT EXISTS(
  SELECT 1 FROM product_catalog WHERE product_id=NEW.id AND confirmed_price_kop=NEW.price_kop)) BEGIN
  SELECT RAISE(ABORT,'LOZA_PRICE_NOT_CONFIRMED');
END;
CREATE TRIGGER IF NOT EXISTS loza_checkout_catalog_guard BEFORE INSERT ON order_checkout BEGIN
  SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.items_json) j
    LEFT JOIN products p ON p.id=json_extract(j.value,'$.productId')
    LEFT JOIN product_catalog c ON c.product_id=p.id
    WHERE p.is_demo=1 OR c.product_id IS NULL OR c.confirmed_price_kop IS NULL OR c.confirmed_price_kop<>p.price_kop)
    THEN RAISE(ABORT,'LOZA_STOCK_UNAVAILABLE') END;
END;

-- Replace only the product-edit trigger, preserving its optimistic locking and audit.
DROP TRIGGER IF EXISTS loza_admin_product;
CREATE TRIGGER loza_admin_product AFTER INSERT ON admin_mutations WHEN NEW.kind='product' BEGIN
  SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM admin_product_versions WHERE product_id=NEW.target AND version=NEW.expected_version)
    THEN RAISE(ABORT,'LOZA_VERSION_CONFLICT') END;
    SELECT NEW.id,NEW.actor,NEW.kind,NEW.target,
      json_object('name',p.name,'priceKop',p.price_kop,'stock',p.stock,'available',p.available,'details',json(p.details_json),
        'priceConfirmed',CASE WHEN c.confirmed_price_kop=p.price_kop THEN 1 ELSE 0 END,'characteristicsConfirmed',c.characteristics_confirmed),NEW.payload_json
      FROM products p LEFT JOIN product_catalog c ON c.product_id=p.id WHERE p.id=NEW.target;
  UPDATE product_catalog SET confirmed_price_kop=CASE WHEN json_extract(NEW.payload_json,'$.priceConfirmed')=1
      THEN json_extract(NEW.payload_json,'$.priceKop') ELSE NULL END,
    characteristics_confirmed=COALESCE(json_extract(NEW.payload_json,'$.characteristicsConfirmed'),0) WHERE product_id=NEW.target;
  UPDATE products SET name=json_extract(NEW.payload_json,'$.name'),price_kop=json_extract(NEW.payload_json,'$.priceKop'),
    stock=json_extract(NEW.payload_json,'$.stock'),available=json_extract(NEW.payload_json,'$.available'),
    details_json=json_extract(NEW.payload_json,'$.detailsJson') WHERE id=NEW.target;
END;

CREATE TABLE IF NOT EXISTS catalog_imports(
  id TEXT PRIMARY KEY,actor TEXT NOT NULL,payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64),
  rows_json TEXT NOT NULL CHECK(json_valid(rows_json) AND json_type(rows_json)='array' AND json_array_length(rows_json) BETWEEN 1 AND 107),
  row_count INTEGER NOT NULL CHECK(row_count=json_array_length(rows_json)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER IF NOT EXISTS loza_catalog_import AFTER INSERT ON catalog_imports BEGIN
    SELECT NEW.id || ':' || json_extract(value,'$.id'),NEW.actor,'product',json_extract(value,'$.id'),
      json_extract(value,'$.version'),json_extract(value,'$.payload') FROM json_each(NEW.rows_json);
END;
INSERT OR IGNORE INTO loza_store_migrations(version) SELECT '0004_catalog_107' WHERE (SELECT COUNT(*) FROM product_catalog)=107;
